/* @lc app=leetcode id=3939 lang=kotlin */ class Solution { fun cv(a: LongArray, b: LongArray, k: Int): LongArray = LongArray(k) { r -> (0 until k).fold(0L) { s, i -> (s + a[i] * b[(r - i + k) % k]) % 1_000_000_007L } } fun countValidSubsets(parent: IntArray, nums: IntArray, k: Int): Int = parent.size.let { n -> Array(n) { LongArray(k).also { a -> a[0] = 1L } }.let { f0 -> Array(n) { v -> LongArray(k).also { a -> a[nums[v] % k] = 1L } }.let { f1 -> (n - 1 downTo 1).forEach { c -> parent[c].let { p -> LongArray(k) { (f0[c][it] + f1[c][it]) % 1_000_000_007L }.let { g -> f0[p] = cv(f0[p], g, k) }.let { f1[p] = cv(f1[p], f0[c], k) } } }.let { ((f0[0][0] + f1[0][0] - 1 + 1_000_000_007L) % 1_000_000_007L).toInt() } } } } }